style.css:
@-moz-document domain("open.spotify.com") {
body {
        filter: invert(100%) !important;
    }

    /* Site colors (inverted) */  
    .encore-dark-theme {
        --text-bright-accent: #e246ab;
        --text-negative: #0c8d80;
        --text-warning: #005bd4;
        --text-positive: #e1289f;
        --text-announcement: #b34c00;
        --essential-bright-accent: #e1289f;
        --essential-negative: #12d3c0;
        --essential-warning: #005bd4;
        --essential-positive: #e1289f;
        --essential-announcement: #b34c00;
    }
    .encore-bright-accent-set {
        --background-base: #e1289f;
        --background-highlight: #c41b88;
        --background-press: #e543ab;
        --background-elevated-base: #c41b88;
        --background-elevated-highlight: #c41b88;
        --background-elevated-press: #e543ab;
        --background-tinted-base: #e1289f;
        --background-tinted-highlight: #e1289f;
        --background-tinted-press: #e1289f;
     } 
    ::selection { 
        background-color: #cc6602;
        color: #000;
    }
    
    /* Global variables */
    icon, 
    img, 
    video, 
    dialog, 
    div[style*="background-image"] {
        filter: invert(100%) !important;
    }
    
    /* Now-playing-bar */ 
    div[style*="--progress-bar-transform"] {
        --is-active-fg-color: #e246ab;
    }
    button[data-active="true"] {
      color: #e246ab !important;
    }  
    button[data-active="true"]::after {
      background-color: #e246ab !important;
    }
   
    /* Home WatchFeed */
    .KYeeT {
        filter: invert(100%) !important;
    }
    
    /* Now playing view */
    div[style*="background-image"] > :not(div[data-encore-id="text"]) {
        filter: invert(100%) !important;
        text-shadow: #000 0 0 10px; 
    }
    
    /* Artist page */
    .contentSpacing {
        text-shadow: #000 0 0 5px; 
    }
    svg {
        --background-base: #b34c00 !important;
    }
    button[style*="background-image"] {
        filter: invert(100%) !important;
        cursor: pointer;
    }

    /* Event page */
    .encore-text-title-medium {
        text-shadow: #000 0 0 10px; 
    }
    
    /* Fullscreen */
    .npv-cross-fade-container {
        filter: invert(100%) !important;
    }
    .npv-up-next__image  {
        filter: invert(0%) !important;
    }
}
